begin read only;set local search_path=pg_catalog;with w as(select id from public.budget_workspaces where name='audit-batch-x-receipt-d7be160c2026') select jsonb_build_object('old_request_rows',(select count(*) from public.business_spending_requests r where r.workspace_id in(select id from w) and r.title='Synthetic replay request'),'old_request_hash',(select md5(coalesce(jsonb_agg(to_jsonb(r) order by r.id),'[]'::jsonb)::text) from public.business_spending_requests r where r.workspace_id in(select id from w) and r.title='Synthetic replay request'),'claim_hash',(select md5(coalesce(jsonb_agg(to_jsonb(c) order by c.id),'[]'::jsonb)::text) from public.business_expense_claims c where c.workspace_id in(select id from w)),'document_hash',(select md5(coalesce(jsonb_agg(to_jsonb(d) order by d.id),'[]'::jsonb)::text) from public.business_documents d where d.workspace_id in(select id from w)),'category_hash',(select md5(coalesce(jsonb_agg(to_jsonb(c) order by c.id),'[]'::jsonb)::text) from public.business_categories c where c.workspace_id in(select id from w)),'dimension_hash',(select md5(coalesce(jsonb_agg(to_jsonb(d) order by d.id),'[]'::jsonb)::text) from public.business_dimensions d where d.workspace_id in(select id from w))) baseline;rollback;
